import React from "react";
import { Table, Typography, Row, Button } from "antd";
import { useQuery } from "@apollo/client";
import {
  StaffMembers,
  StaffMembersRes
} from "graphql-src/staff/queries";
import { Link } from 'react-router-dom'
import styled from 'styled-components'

const { Text } = Typography;

const ButtonRow = styled(Row)`
  margin-bottom: 15px
`

const StaffList = () => {
  const columns = [
    {
      title: "Name",
      dataIndex: "name",
      key: "name",
      render: (values: { name: string; id: string; }) => <Link to={`companies/${values.id}&${values.name}`}>{values.name}</Link>,
    },
    {
      title: "Email Address",
      dataIndex: "email",
      key: "email",
    },
    {
      title: "Role",
      dataIndex: "role",
      key: "role",
    },
    {
      title: "Status",
      dataIndex: "status",
      key: "status",
      render: (status: string) => {
        return (
          <Text type={
            status === 'Active'
              ? 'success'
              : 'danger'
          } key={status}>
            {status}
          </Text>
        );
      },
    }
  ];

  const { data, loading } = useQuery<StaffMembersRes>(StaffMembers)

  return (
    <div>
      <ButtonRow justify="end">
        <Link to="/app/staff/add">
          <Button type="primary">Add New User</Button>
        </Link>
      </ButtonRow>
      <Table
        columns={columns}
        loading={loading}
        dataSource={!!data ? data.admins.map(member => ({
          key: member.id,
          name: {
            name: member.name,
            id: member.id
          },
          email: member.email,
          role: 'Admin',
          status: 'Active'
        })) : []} 
      />
    </div>
  );
};

export default StaffList;
